create function public.project_analytics(p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare months jsonb; cats jsonb; budgets jsonb; month_spend bigint; begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if;
select coalesce(jsonb_agg(to_jsonb(r)),'[]') into months from (select to_char(e.event_date,'YYYY-MM') as "month",sum(case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end)::text amount_minor from public.ledger_entries l join public.financial_accounts a on a.id=l.account_id join public.financial_events e on e.id=l.financial_event_id where l.project_id=p_project and a.account_type='EXPENSE' group by 1 order by 1) r;
select coalesce(jsonb_agg(to_jsonb(r)),'[]') into cats from (select coalesce(c.name,'Uncategorized') category,sum(case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end)::text amount_minor from public.ledger_entries l join public.financial_accounts a on a.id=l.account_id left join public.categories c on c.id=l.category_id where l.project_id=p_project and a.account_type='EXPENSE' group by 1 order by 1) r;
select coalesce(sum(case l.direction when 'DEBIT' then l.amount_minor else -l.amount_minor end),0) into month_spend from public.ledger_entries l join public.financial_accounts a on a.id=l.account_id join public.financial_events e on e.id=l.financial_event_id where l.project_id=p_project and a.account_type='EXPENSE' and date_trunc('month',e.event_date)=date_trunc('month',current_date);
budgets:=public.report_data(p_project,'budget_lines'); return jsonb_build_object('months',months,'categories',cats,'budgets',budgets,'current_month_minor',month_spend::text,'issues',public.finance_issues(p_project)); end $$;
create function public.generate_recurring_drafts(p_project uuid) returns integer language plpgsql security definer set search_path='' as $$ declare r public.recurring_expense_templates; count integer:=0; due date; begin perform private.assert_finance(p_project); perform 1 from public.projects where id=p_project and status='active' for update; if not found then raise exception 'PROJECT_CLOSED'; end if; for r in select * from public.recurring_expense_templates where project_id=p_project and active and next_due_date<=current_date for update loop due:=r.next_due_date; insert into public.notifications(user_id,project_id,type,title,body,entity_type,entity_id,dedupe_key) values(auth.uid(),p_project,'recurring_due',r.description,r.amount_minor::text,'recurring_expense_templates',r.id,'recurring:'||r.id||':'||due) on conflict(dedupe_key) do nothing; update public.recurring_expense_templates set next_due_date=case r.recurrence_rule when 'weekly' then due+7 when 'monthly' then (due+interval '1 month')::date else (due+interval '1 year')::date end where id=r.id; count:=count+1; end loop; return count; end $$;
revoke all on function public.project_analytics(uuid),public.generate_recurring_drafts(uuid) from public;
grant execute on function public.project_analytics(uuid),public.generate_recurring_drafts(uuid) to authenticated;
